def stop_value(n, quotes):
    k = len(quotes)
    value = sum(quotes) / k
    for _ in range(n - 1):
        value = sum(max(q, value) for q in quotes) / k
    return value

def unbounded_knapsack(weights, values, cap):
    dp = [0] * (cap + 1)
    for w in range(1, cap + 1):
        for wt, val in zip(weights, values):
            if wt <= w:
                dp[w] = max(dp[w], dp[w - wt] + val)
    return dp[cap]
